const { normalizePageSize } = require('./page-size.cjs')
function pageRows(rows, requestedSize) {
  return rows.slice(0, normalizePageSize(requestedSize))
}
module.exports = { pageRows }

'use strict'
const MAX_PAGE_SIZE = 200
function normalizePageSize(value) {
  if (!Number.isInteger(value)) return 20
  return Math.min(MAX_PAGE_SIZE, Math.max(1, value))
}
module.exports = { normalizePageSize }

'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const { normalizePageSize } = require('../src/page-size.cjs')
const { pageRows } = require('../src/list-page.cjs')
test('integer page size is bounded', () => {
  for (const [input, expected] of [[0, 1], [-4, 1], [50, 50], [150, 150], [999, 200]]) {
    assert.equal(normalizePageSize(input), expected)
  }
})
test('non-integers keep the default', () => {
  for (const input of [undefined, '200', 1.5, NaN]) assert.equal(normalizePageSize(input), 20)
})
test('the caller uses the normalized size', () => {
  assert.equal(pageRows(Array.from({ length: 300 }, (_, i) => i), 999).length, 200)
})
